import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.CQxpk36T.js";const g=JSON.parse(`{"title":"L'éditeur de la page","description":"","frontmatter":{},"headers":[],"relativePath":"guide/editeur.md","filePath":"guide/editeur.md","lastUpdated":1793572677000}`),s={name:"guide/editeur.md"};function n(i,e,u,d,l,c){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="l-editeur-de-la-page" tabindex="-1">L&#39;éditeur de la page <a class="header-anchor" href="#l-editeur-de-la-page" aria-label="Permalink to &quot;L&#39;éditeur de la page&quot;">​</a></h1><p>Le <strong>crayon</strong> en haut à droite (ou Réglages → Propriété → Éditer) ouvre l&#39;éditeur. Touchez un bâtiment : il devient une maquette retouchable, les autres restent en place. Tout se règle au doigt, sans écrire de code.</p><h2 id="ce-qu-on-peut-retoucher" tabindex="-1">Ce qu&#39;on peut retoucher <a class="header-anchor" href="#ce-qu-on-peut-retoucher" aria-label="Permalink to &quot;Ce qu&#39;on peut retoucher&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rubrique</th><th></th></tr></thead><tbody><tr><td><strong>Position</strong></td><td>« Déplacer au doigt », puis glisser sur la scène (la caméra ne tourne plus tant que le bouton est actif) ; ou régler au centimètre, et l&#39;orientation au degré. « Faîtage dans l&#39;autre sens » tourne le toit d&#39;un quart de tour sur la même emprise</td></tr><tr><td><strong>Dimensions</strong></td><td>Longueur (le long du faîtage), largeur, haut des murs, faîtage ; biais de chaque bout, en degrés (<a href="/HAven-docs/guide/batiments#pignons-en-biais">pignons en biais</a>)</td></tr><tr><td><strong>Toit</strong></td><td>Deux pans, ou appentis (haut côté cour ou côté dos) ; auvent ouvert sur poteaux</td></tr><tr><td><strong>Bâtiment</strong></td><td>Nom et type (couleurs, icône)</td></tr></tbody></table><p><strong>Ajouter un bâtiment</strong> pose une cabane de 6 × 4 m sur le point de la cour, avec une porte et une pièce (Zone Home Assistant du même identifiant que le bâtiment). <strong>Retirer</strong> l&#39;enlève, avec ce qui s&#39;y rattache (parcours des poules, panneaux solaires).</p><h2 id="enregistrer" tabindex="-1">Enregistrer <a class="header-anchor" href="#enregistrer" aria-label="Permalink to &quot;Enregistrer&quot;">​</a></h2><p>Les retouches forment un <strong>brouillon</strong>, gardé dans le navigateur tant qu&#39;il n&#39;est pas enregistré.</p><ul><li>Avec <code>npm run dev</code>, <strong>Enregistrer</strong> écrit <code>proprietes/&lt;nom&gt;/retouches.json</code> et recharge la page : portes, fenêtres et noues sont recalculées.</li><li>Sur un serveur, le bouton devient <strong>Télécharger</strong> : déposez le fichier dans le dossier de la propriété, puis relancez <code>npm run deploy</code>.</li></ul><h2 id="comment-les-retouches-s-appliquent" tabindex="-1">Comment les retouches s&#39;appliquent <a class="header-anchor" href="#comment-les-retouches-s-appliquent" aria-label="Permalink to &quot;Comment les retouches s&#39;appliquent&quot;">​</a></h2><p><code>retouches.json</code> s&#39;applique <strong>par-dessus</strong> <code>site.json</code> et <code>propriete.ts</code> : une section retouchée prend l&#39;emprise et les hauteurs du fichier. Pour revenir à la description d&#39;origine, supprimez son entrée (ou le fichier). Le format est décrit dans la <a href="/HAven-docs/reference/retouches">référence</a>.</p><div class="warning custom-block"><p class="custom-block-title">Ce qui ne suit pas</p><p>Les parcours des poules, places de parking, cours et allées ne suivent pas un bâtiment déplacé : reprenez leurs coordonnées à la main dans <code>propriete.ts</code>.</p></div><h2 id="relever-une-position" tabindex="-1">Relever une position <a class="header-anchor" href="#relever-une-position" aria-label="Permalink to &quot;Relever une position&quot;">​</a></h2><p>Les pièces, portes et fenêtres se décrivent dans <code>propriete.ts</code>, avec des positions le long des murs. <strong>Relever une position</strong> (dans l&#39;éditeur, ou Réglages → Propriété) donne ces valeurs : touchez un mur, lisez par exemple</p><blockquote><p>Maison · côté cour · at: 2.35 · hauteur 1.20 m</p></blockquote><p>et reportez-les dans la <a href="/HAven-docs/guide/facades#les-portes">porte</a> ou la <a href="/HAven-docs/guide/facades#placer-les-fenetres-a-la-main">fenêtre</a> voulue. <strong>Copier</strong> met le texte dans le presse-papiers.</p><table tabindex="0"><thead><tr><th>Touché</th><th>Texte relevé</th></tr></thead><tbody><tr><td>Un long pan</td><td><code>Maison · côté cour · at: 2.35 · hauteur 1.20 m</code></td></tr><tr><td>Un pignon</td><td><code>Maison · pignon +x · at: -1.10 · hauteur 3.40 m</code> (<code>at</code> en travers)</td></tr><tr><td>Un toit</td><td><code>Maison · toit · le long du faîtage -3.00 m</code> (pour les panneaux solaires)</td></tr><tr><td>Le sol</td><td><code>Sol · x: 9.25, z: 6.00</code> (place de parking, arbre, coin d&#39;enclos)</td></tr></tbody></table><p>Un bâtiment à plusieurs sections précise laquelle : <code>Maison, section 1 · …</code>.</p>',17)])])}const h=t(s,[["render",n]]);export{g as __pageData,h as default};
